import type { Circuit } from "@pitwall/shared";
import registry from "./circuits.json";

// Generated by scripts/gen-circuits.mjs from f1db (CC BY 4.0), Jolpica and Open-Meteo.
const timezones = registry.timezones as Record<string, string>;
const layoutLength = registry.layoutLength as Record<string, number | null>;
const races = registry.races as unknown as Record<string, [circuitId: string, layoutId: string]>;

interface JolpicaCircuit {
  circuitId: string;
  circuitName: string;
  Location: { lat: string; long: string; locality: string; country: string };
}

/** Jolpica circuit + registry metadata. The layout is only attached when the registry agrees on the circuit. */
export function circuitFor(c: JolpicaCircuit, season: number, round: number): Circuit {
  const race = races[`${season}/${round}`];
  const layoutId = race && race[0] === c.circuitId ? race[1] : null;
  return {
    id: c.circuitId,
    name: c.circuitName,
    locality: c.Location.locality,
    country: c.Location.country,
    lat: Number(c.Location.lat),
    lon: Number(c.Location.long),
    timezone: timezones[c.circuitId] ?? null,
    layout: layoutId ? { id: layoutId, lengthKm: layoutLength[layoutId] ?? null } : null,
  };
}
